const namesByAlias = new Map<string, { en: string; fr: string }>();
for (const [en, fr] of Object.entries(TRAINER_NAME_I18N_FR)) namesByAlias.set(fr, { en, fr });
// English keys take precedence when several classes share a French display name.
for (const [en, fr] of Object.entries(TRAINER_NAME_I18N_FR)) namesByAlias.set(en, { en, fr });

// Legacy Kanto names, including spellings still present in saved encounters.
const legacyAliases: Record<string, string> = {
    Bleu: 'Blue',
    Recrue: 'Grunt',
    Jeune: 'Youngster',
    Demoiselle: 'Lass',
    'Top Model': 'Beauty',
    Karateka: 'Black Belt',
    Oiseleur: 'Bird Keeper',
    Psy: 'Psychic',
    'Géomancien': 'Hiker',
    'VÃ©tÃ©ran': 'Veteran',
    'GÃ©omancien': 'Hiker',
    'IngÃ©nieur': 'Engineer',
};
for (const [alias, en] of Object.entries(legacyAliases)) {
    const names = namesByAlias.get(en);
    if (names) namesByAlias.set(alias, names);
}

/** Plain text only; callers embedding HTML must escape the result. */
export function localizeTrainerName(name: string, language: string = 'fr'): string {
    const names = namesByAlias.get(name);
    return names ? names[language === 'en' ? 'en' : 'fr'] : name;
}
